<template>
	<view class="container">
		<u-loading-page
		:loading="true" 
		v-if="load"
		fontSize="28rpx" />
		<view class="inner" v-else>
			<view class="inner-groups">
				<view class="inner-group">
					<view class="title">基本信息</view>
					<view class="form">
						<view class="form-row">
							<text class="row-left">真实姓名</text>
							<view class="row-input">
								<u-input
								    placeholder="请输入真实姓名"
									border="none"
									placeholderClass="placeholder30"
									v-model="form.realname"
								    clearable />
							</view>
						</view>
						<view class="form-row">
							<text class="row-left">身份证号</text>
							<view class="row-input">
								<u-input
								    placeholder="请输入身份证号"
									border="none"
									type="idcard"
									placeholderClass="placeholder30"
									v-model="form.idcard"
								    clearable />
							</view>
						</view>
					</view>
				</view>
				<view class="inner-group">
					<view class="title">上传身份证</view>
					<view class="upload-info">
						<view class="upload-item">
							<view class="upload-item-img" @click="chooseImage()">
								<image :src="form.person_cert ? getFullUrl(form.person_cert) : '/static/my/sfz-zheng.png'" mode="aspectFit" class="upload-img" />
							</view>
							<view class="upload-text">上传人像面</view>
						</view>
						<view class="upload-item">
							<view class="upload-item-img" @click="chooseImage('person_cert1')">
								<image :src="form.person_cert1 ? getFullUrl(form.person_cert1) : '/static/my/sfz-fan.png'" mode="aspectFit" class="upload-img" />
							</view>
							<view class="upload-text">上传国徽面</view>
						</view>
					</view>
				</view>
				<view class="inner-group" v-if="false">
					<view class="title">人脸识别</view>
					<view class="rlsb-info">
						<image src="@/static/my/rlsb.png" mode="widthFix" class="rlsb-img" />
						<button size="mini" class="rlsb-btn">开始识别</button>
					</view>
				</view>
			</view>
			<view class="submit">
				<button type="default" class="submit-btn" @click="submit"
					:disabled="submitDisabled">立即认证</button>
			</view>
		</view>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	import md5 from '@/components/MD5.js';
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					realname:'',
					idcard:'',
					person_cert:'',
					person_cert1:'',
				},
				submitDisabled:false
			}
		},
		onLoad(e) {
			_this = this;
			_this.tijiao()
		},
		methods: {
			chooseImage(field='person_cert'){
				uni.chooseImage({
					count:1, //默认9
					sizeType: ['original', 'compressed'], //可以指定是原图还是压缩图，默认二者都有
					//album 从相册选图，camera 使用相机，默认二者都有。如需直接开相机或直接选相册，请只使用一个选项
					sourceType: ['album','camera'], 
					success(res) {
						const tempFilePath = res.tempFilePaths[0]
						_this.upload_pic(tempFilePath,field)
					}
				});
			},
			async upload_pic(file,field){
				let sign_prefix=getApp().globalData.sign_prefix
				let token = _this.user_token
				let sign=md5.hax_md5('pathperson_cert'+ sign_prefix + token + sign_prefix).toLocaleLowerCase()
				uni.uploadFile({
					url: _this.baseUrl+'/port/put_file',
					filePath: file,
					name: 'file',
					header:{
						token:token
					},
					formData:{
						'path':'person_cert',
						sign:sign
					},
					success: (result) => {
						let data=JSON.parse(result.data)
						if(data.code==200){
							_this.form[field] = data.result.file
						}else{
							uni.$u.toast(data.msg)
						}
					}
				});
			},
			submit(){
				_this.form.step = 2
				_this.tijiao()
			},
			//提交
			async tijiao(){
				if (_this.form.step == 2) {
					var rule = [
					{
						name: 'realname',
						rules: ['require', 'chn'],
						errorMsg: {
							require: '请输入真实姓名',
							chn: '真实姓名只能为中文',
						}
					},{
						name: 'idcard',
						rules: ['require'],
						errorMsg: {
							require: '请输入身份证号',
						}
					},{
						name: 'person_cert',
						rules: ['require'],
						errorMsg: {
							require: '请上传人像面',
						}
					}, {
						// 字段名
						name: 'person_cert1',
						rules: ['require'],
						errorMsg: {
							require: '请上传国徽面',
						}
					}];
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/edit_user_sm',_this.form)
				if (data.code==200) {
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code == -50){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code == -1){
					_this.mobile = data.result.mobile
					_this.form.realname = data.result.realname
					_this.form.idcard = data.result.idcard
					_this.form.person_cert = data.result.person_cert
					_this.form.person_cert1 = data.result.person_cert1
					if (_this.load) {
						_this.load = false
					}
				}else{
					uni.$u.toast(data.msg)
				}
			}
		}
	}
</script>

